arguments.command:
mkdir -p /app/out; cat > /app/make.py <<'E'
import csv,json,collections
W={};M=collections.Counter()
def add(w,month,kg,st):
    if st.strip().lower()!='delivered':return
    d=W.setdefault(w,[0,0.0]);d[0]+=1;d[1]+=kg;M[month]+=1
for r in csv.DictReader(open('/app/data/east.csv')):
    add('east',r['shipped'][:7],float(r['weight_kg']),r['status'])
for r in csv.DictReader(open('/app/data/west.csv'),delimiter=';'):
    d,m,y=r['shipped'].split('.');add('west',f'{y}-{m}',float(r['weight_lb'].replace(',','.'))*0.45359237,r['status'])
for l in open('/app/data/north.jsonl'):
    if l.strip():
        r=json.loads(l);add('north',r['shipped_at'][:7],r['weight_g']/1000,r['status'])
out={"warehouses":{k:{"shipments":v[0],"total_kg":round(v[1],2)} for k,v in sorted(W.items())},"by_month":dict(sorted(M.items()))}
json.dump(out,open('/app/out/summary.json','w'),indent=2);print(out)
E
python3 /app/make.py
echo '{"status":"success","summary":"Parsed the three warehouse exports, normalized units/dates, excluded cancelled/returned rows, and wrote /app/out/summary.json."}' > /app/STATUS.json

